import { AddCommand, RemoveCommand, MoveCommand } from './commands';

const Cmd = { ADD: 'add', REMOVE: 'remove', MOVE: 'move' };

class CommandManager {
  commands = {
    [Cmd.ADD]: AddCommand,
    [Cmd.REMOVE]: RemoveCommand,
